                        q.append(z)
            result.append((color, cells))
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = components(grid)
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    guides = []
    for color, cells in comps:
        if color == bg:
            continue
        sides = set()
        for r, c in cells:
            if r == 0: sides.add('top')
            if r == h-1: sides.add('bottom')
            if c == 0: sides.add('left')
            if c == w-1: sides.add('right')
        if len(sides) < 2:
            continue
        points = set(cells)
        elbows = []
        for r, c in cells:
            horiz = ((r, c-1) in points, (r, c+1) in points)
            vert = ((r-1, c) in points, (r+1, c) in points)
            if any(horiz) and any(vert):
                # A corner has exactly one horizontal and one vertical neighbor.
                if sum(horiz) == 1 and sum(vert) == 1:
                    elbows.append((r, c, horiz, vert))
        if not elbows:
            continue
        # The guide's elbow is at a bounding-box corner, not an interior bend.
        rmin, rmax = min(r for r, c in cells), max(r for r, c in cells)
        cmin, cmax = min(c for r, c in cells), max(c for r, c in cells)
        corners = [e for e in elbows if (e[0] in (rmin, rmax) and e[1] in (cmin, cmax))]
        if not corners:
            corners = elbows
        # A guide touching two borders has its elbow farthest from the two borders it touches.
        def score(e):
            r, c, _, _ = e
            return min((r if 'top' in sides else h-1-r),
                       (c if 'left' in sides else w-1-c))
        elbow = max(corners, key=score)
        guides.append((len(cells), color, cells, elbow, sides))
    if not guides:
        return [row[:] for row in grid]
    _, guide_color, guide_cells, elbow, sides = max(guides, key=lambda x: x[0])
    er, ec, horiz, vert = elbow
    # The open quadrant lies opposite the guide's two arms.
    dr = -1 if vert[1] else 1  # if arm goes down, open upward; otherwise open downward
    dc = -1 if horiz[1] else 1  # if arm goes right, open leftward; otherwise open rightward
    candidates = []
    guide_set = set(guide_cells)
    for color, cells in comps:
        if color == bg or color == guide_color or set(cells) & guide_set:
            continue
        # Consider components occupying the guide's inward-facing quadrant; the
        # closest pixel may lie on the guide's elbow row or column.
        inward = [(r, c) for r, c in cells if (r-er)*dr >= 0 and (c-ec)*dc >= 0]
